:root {
  /* display: 32px di 360px -> 56px di 1280px */
  --fs-display: clamp(2rem, 1.413rem + 2.609vw, 3.5rem);
  /* headline: 24px -> 36px */
  --fs-headline: clamp(1.5rem, 1.207rem + 1.304vw, 2.25rem);
  /* body: 16px -> 18px */
  --fs-body: clamp(1rem, 0.951rem + 0.217vw, 1.125rem);
}

:root {
  /* Hijau brand */
  --hijau-hex: #0F766E;
  --hijau-rgb: rgb(15 118 110);
  --hijau-hsl: hsl(175 77% 26%);

  /* Oranye aksen */
  --oranye-hex: #EA580C;          /* rgb(234 88 12)  hsl(21 90% 48%) */

  /* Abu teks */
  --abu-hex: #334155;             /* rgb(51 65 85)   hsl(215 25% 27%) */

  /* CSS modern: oklch, kira-kira setara hijau brand */
  --hijau-oklch: oklch(51% 0.09 185);
}

/* sumber:
   color.brand.600     = #0F766E
   color.text.default  = {color.neutral.900}
   color.neutral.900   = #0F172A
   space.2 = 8px, space.4 = 16px, radius.md = 10px */
:root {
  --color-brand-600: #0F766E;
  --color-text-default: var(--color-neutral-900);
  --color-neutral-900: #0F172A;
  --space-2: 8px;
  --space-4: 16px;
  --radius-md: 10px;
}

.artikel p {
  font-size: 1rem;
  line-height: 1.6;
  max-width: 65ch;              /* ± 65 karakter per baris */
  text-wrap: pretty;            /* kurangi kata yatim di akhir paragraf */
}
.artikel h1 { font-size: 2.25rem; line-height: 1.15; letter-spacing: -0.02em; text-wrap: balance; }
.eyebrow    { font-size: .75rem; text-transform: uppercase; letter-spacing: .08em; }
